args.source:
import type { Plugin } from "../../kernel/types";

const plugin: Plugin = {
  id: "result-panel",
  name: "Result Panel",
  version: "1.0.0",
  onLoad(ctx) {
    ctx.register({
      kind: "api",
      api: {
        mount: "panel",
        router: async () => ({ title: "Panel", html: "<p>value=29</p>" }),
      },
    });
  },
};

export default plugin;

